messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>3D Car Race</title>
<style>
  *{margin:0;padding:0;box-sizing:border-box}
  body{overflow:hidden;background:#000}
  canvas{display:block}
</style>
</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "https://unpkg.com/three@0.160.0/build/three.module.js"
  }
}
</script>
<script type="module">
import * as THREE from 'three';

// ─── SC ‐ ───
const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(50, innerWidth/innerHeight, 0.1, 500);
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
document.body.appendChild(renderer.domElement);

// ─── SKY & GROUND
scene.background = new THREE.Color(0x87CEEB);
scene.fog = new THREE.Fog(0x87CEEB, 120, 350);
const gnd = new THREE.Mesh(new THREE.PlaneGeometry(500, 500), new THREE.MeshLambertMaterial({color:0x3a7c3a}));
gnd.rotation.x = -Math.PI/2;
scene.add(gnd);
scene.add(new THREE.AmbientLight(0x6688cc, 0.6));
const sun = new THREE.DirectionalLight(0xffffff, 0.9);
sun.position.set(30, 60, 40);
scene.add(sun);

// ─── R track
const TRACK_W=18, TRACK_L=220;
const trackGeo=new THREE.PlaneGeometry(TRACK_W,TRACK_L,1,1);
const trackMat=new THREE.MeshLambertMaterial({color:0x444444});
const track=new THREE.Mesh(trackGeo,trackMat);
track.rotation.x=-Math.PI/2;
track.position.set(0,0.01,0);
scene.add(track);

// lane dashes
for(let z=-100;z<100;z-=8){
  const s=new THREE.Mesh(new THREE.PlaneGeometry(0.15,3.5),new THREE.MeshBasicMaterial({color:0xffffff}));
  s.rotation.x=-Math.PI/2;s.position.set(0,0.02,z);scene.add(s);
}
// edge lines
[-8.5,8.5].forEach(x=>{
  const m=new THREE.Mesh(new THREE.PlaneGeometry(0.3,TRACK_L),new THREE.MeshBasicMaterial({color:0xcccccc}));
  m.rotation.x=-Math.PI/2;m.position.set(x,0.02,0);scene.add(m);
});

// ─── R line
const FINISH_Z=80;
const flGeo=new THREE.PlaneGeometry(TRACK_W,2);
for(let i=0;i<8;i++){
  const c=new THREE.MeshBasicMaterial({color:(i%2===0)?0xffffff:0x000000});
  const fl=new THREE.Mesh(flGeo,c);
  fl.rotation.x=-Math.PI/2;fl.position.set(0,0.03,FINISH_Z+(i-3.5)*0.25);
  scene.add(fl);
}
// finish post
const postGeo=new THREE.BoxGeometry(0.4,4,0.4);
const postMat=new THREE.MeshLambertMaterial({color:0xdddddd});
[-8,8].forEach(x=>{
  const p=new THREE.Mesh(postGeo,postMat);
  p.position.set(x,2,FINISH_Z);scene.add(p);
});
// banner
const banGeo=new THREE.BoxGeometry(20,1.5,0.1);
const banMat=new THREE.MeshLambertMaterial({color:0xff2222});
const ban=new THREE.Mesh(banGeo,banMat);
ban.position.set(0,4.5,FINISH_Z);scene.add(ban);
// small flag on each post
const flagGeo=new THREE.PlaneGeometry(1.5,0.8);
const flagMat=new THREE.MeshLambertMaterial({color:0xffcc00});
[-8,8].forEach(x=>{
  const f=new THREE.Mesh(flagGeo,flagMat);
  f.position.set(x,4.5,FINISH_Z);scene.add(f);
});

// ─── CAR BUILDER
function makeCar(color, laneX) {
  const g = new THREE.Group();
  const bodyMat = new THREE.MeshLambertMaterial({color});
  const glassMat = new THREE.MeshLambertMaterial({color:0x88ccff});
  const wheelMat = new THREE.MeshLambertMaterial({color:0x222222});
  const hubMat = new THREE.MeshLambertMaterial({color:0xaaaaaa});

  // main body
  const body = new THREE.Mesh(new THREE.BoxGeometry(2.6,0.85,5.5),bodyMat);
  body.position.y = 0.55;
  g.add(body);
  // cabin
  const cabin = new THREE.Mesh(new THREE.BoxGeometry(2.2,0.65,2.8),glassMat);
  cabin.position.set(0,1.25,-0.5);
  g.add(cabin);
  // hood
  const hood = new THREE.Mesh(new THREE.BoxGeometry(2.5,0.15,1.8),bodyMat);
  hood.position.set(0,1.05,1.8);
  g.add(hood);
  // rear spoiler
  const spoiler = new THREE.Mesh(new THREE.BoxGeometry(2.8,0.08,0.6),bodyMat);
  spoiler.position.set(0,1.0,-2.6);
  g.add(spoiler);
  // front splitter
  const splitter = new THREE.Mesh(new THREE.BoxGeometry(2.7,0.08,0.4),bodyMat);
  splitter.position.set(0,0.2,2.8);
  g.add(splitter);
  // wheels
  const wheelGeo = new THREE.CylinderGeometry(0.45,0.45,0.35,16);
  [[-1.3,0.45,1.6],[1.3,0.45,1.6],[-1.3,0.45,-1.8],[1.3,0.45,-1.8]].forEach(p=>{
    const w=new THREE.Mesh(wheelGeo,wheelMat);
    w.rotation.z=Math.PI/2;w.position.set(...p);g.add(w);
    const h=new THREE.Mesh(new THREE.CylinderGeometry(0.15,0.15,0.36,8),hubMat);
    h.rotation.z=Math.PI/2;h.position.set(...p);g.add(h);
  });
  // headlights
  const hlMat=new THREE.MeshBasicMaterial({color:0xffffaa});
  [-0.8,0.8].forEach(x=>{
    const hl=new THREE.Mesh(new THREE.SphereGeometry(0.15,8,6),hlMat);
    hl.position.set(x,0.65,2.75);g.add(hl);
  });
  // tail lights
  const tlMat=new THREE.MeshBasicMaterial({color:0xff0000});
  [-0.8,0.8].forEach(x=>{
    const tl=new THREE.Mesh(new THREE.BoxGeometry(0.4,0.15,0.05),tlMat);
    tl.position.set(x,0.65,-2.75);g.add(tl);
  });

  g.position.set(laneX, 0, 0);
  return g;
}

const redCar = makeCar(0xff1111, -4);
const blueCar = makeCar(0x1144ff, 4);
scene.add(redCar);
scene.add(blueCar);

// ─── C 
const DURATION=7;
const FINISH_LINE=80;
let t=0;
let lastTs=0;

function easeInOut(t){return t<0.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2;}

function updateCars(time){
  // red: 0→1 over DURATION seconds
  const redT = Math.min(easeInOut(Math.min(time/DURATION, 1)), 1);
  // blue: 0→1, slightly ahead initially then red catches up
  const blueT = Math.min(easeInOut(Math.min(time/DURATION*0.95, 1)), 1);

  const redZ = -100 + redT * (FINISH_LINE + 15);
  const blueZ = -100 + blueT * (FINISH_LINE + 15);

  redCar.position.z = redZ;
  blueCar.position.z = blueZ;
}

// ─── CAMERA
function updateCamera(){
  const leadZ = Math.max(redCar.position.z, blueCar.position.z);
  const target = new THREE.Vector3(0, 5, leadZ + 18);
  camera.position.lerp(target, 0.05);
  const lookAt = new THREE.Vector3(0, 2, leadZ - 15);
  const currentLook = new THREE.Vector3();
  camera.getWorldDirection(currentLook);
  camera.lookAt(lookAt);
}

// ─── R
function onResize(){
  camera.aspect = innerWidth/innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
}
window.addEventListener('resize', onResize);

// ─── R
function animate(ts){
  requestAnimationFrame(animate);
  const dt = Math.min((ts - lastTs)/1000, 0.05);
  lastTs = ts;
  t += dt;
  if(t >= DURATION){
    t = 0;
    redCar.position.z = -100;
    blueCar.position.z = -100;
  }
  updateCars(t);
  updateCamera();
  renderer.render(scene, camera);
}
animate(0);
</script>
</body>
</html>
```
